from pathlib import Path
import gzip,hashlib,json
P=Path(__file__).resolve().parents[1];raw=(P/'preview-medium.html').read_bytes();packed=gzip.compress(raw,compresslevel=9,mtime=0);parts=[]
(P/'runtime').mkdir(exist_ok=True)
for n,start in enumerate(range(0,len(packed),650000)):
 data=packed[start:start+650000];name=f'runtime/part-{n:02d}.bin';(P/name).write_bytes(data);parts.append({'file':name,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest()})
records={}
for style in ['medium','long']:
 source=(P/f'preview-{style}.html').read_bytes();digest=hashlib.sha256(source).hexdigest();html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>完整发型 / 人物总平台 · R04</title><link rel="icon" href="data:,"><body style="background:white;color:#40503e;font-family:system-ui"><p style="padding:30px">正在载入人物与发型…</p><script>(async()=>{try{const query=decodeURIComponent(location.search.slice(1)),base=query.startsWith('https://raw.githubusercontent.com/')?query:location.href,files='''+json.dumps([p['file'] for p in parts])+''';const chunks=await Promise.all(files.map(async f=>{const r=await fetch(new URL(f,base));if(!r.ok)throw Error('页面数据暂时无法读取');return new Uint8Array(await r.arrayBuffer());}));const bytes=new Uint8Array(chunks.reduce((n,x)=>n+x.length,0));let offset=0;for(const c of chunks){bytes.set(c,offset);offset+=c.length;}const buffer=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();let html=new TextDecoder().decode(buffer);if('''+json.dumps(style)+'''==='long')html=html.replace('name="hair-default-style" content="medium"','name="hair-default-style" content="long"');const check=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(html)),hash=Array.from(new Uint8Array(check),x=>x.toString(16).padStart(2,'0')).join('');if(hash!=='''+json.dumps(digest)+''')throw Error('页面完整性检查失败');document.open();document.write(html);document.close();}catch(error){document.body.textContent='载入失败：'+error.message;console.error(error);}})();</script></body></html>'''
 f=f'public-{style}.html';(P/f).write_text(html,encoding='utf-8');records[style]={'file':f,'bytes':len(html.encode()),'sha256':hashlib.sha256(html.encode()).hexdigest(),'decompressedBytes':len(source),'decompressedSHA256':digest}
(P/'public.html').write_bytes((P/'public-medium.html').read_bytes());(P/'PUBLIC_BUILD.json').write_text(json.dumps({'transport':'lossless gzip split into small transport parts; final source SHA256 checked before document.write','runtimeBytes':len(packed),'parts':parts,'wrappers':records},indent=2),encoding='utf-8');print('Source bytes',len(raw),'compressed bytes',len(packed),'parts',len(parts))
